canvas.onpointerdown=e=>{canvas.focus();if(mode!=='build')return;e.preventDefault();canvas.setPointerCapture(e.pointerId);let pt=worldPoint(e);pointer=pt;lastCell='';if(tool==='pan'||e.button===1||keys.Space){drag={kind:'pan',screen:screenPoint(e),x:camera.x,y:camera.y};canvas.style.cursor='grabbing';return}if(e.button!==2&&tool!=='erase'&&world.goal&&overlap({x:pt.x,y:pt.y,w:1,h:1},goalBox())){drag={kind:'goal',dx:pt.x-world.goal.x,dy:pt.y-world.goal.y};return}drag={kind:'paint',erase:e.button===2};editAt(pt,drag.erase)};
canvas.onpointermove=e=>{pointer=worldPoint(e);if(mode!=='build'||!drag)return;if(drag.kind==='pan'){let sp=screenPoint(e);camera.x=drag.x+(drag.screen.x-sp.x)/camera.zoom;camera.y=drag.y+(drag.screen.y-sp.y)/camera.zoom;updateView()}else if(drag.kind==='goal'){world.goal={x:Math.round((pointer.x-drag.dx)/25)*25,y:Math.round((pointer.y-drag.dy+65)/25)*25-65}}else if(['block','coin','spike','erase'].includes(tool)||drag.erase){editAt(pointer,drag.erase)}};
canvas.onpointerup=canvas.onpointercancel=e=>{if(drag?.kind==='goal'){persistEdit();toast('Finish moved. You can drag it again anytime.')}drag=null;lastCell='';canvas.style.cursor=mode==='build'?'crosshair':'default';if(canvas.hasPointerCapture?.(e.pointerId))canvas.releasePointerCapture(e.pointerId)};
canvas.onpointerleave=()=>{if(!drag)pointer=null};
function zoomView(factor,anchor={x:500,y:300}){if(mode!=='build')return;let old=camera.zoom;camera.zoom=Math.max(.25,Math.min(2,old*factor));camera.x+=anchor.x/old-anchor.x/camera.zoom;camera.y+=anchor.y/old-anchor.y/camera.zoom;updateView()}
canvas.addEventListener('wheel',e=>{if(mode!=='build')return;e.preventDefault();if(e.ctrlKey||e.metaKey)zoomView(e.deltaY<0?1.1:1/1.1,screenPoint(e));else{camera.x+=e.deltaX/camera.zoom;camera.y+=e.deltaY/camera.zoom;updateView()}},{passive:false});
$('#zoomIn').onclick=()=>zoomView(1.25);$('#zoomOut').onclick=()=>zoomView(.8);$('#homeView').onclick=centerStart;
window.addEventListener('keydown',e=>{if($('#gamesMenu').open)return;if(['INPUT','SELECT','TEXTAREA','BUTTON'].includes(e.target.tagName))return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='KeyR')restart();if(mode==='build'&&e.code==='Home')centerStart()});window.addEventListener('keyup',e=>{keys[e.code]=false});window.addEventListener('blur',()=>{keys={};jumpHeld=false});document.addEventListener('visibilitychange',()=>{keys={};last=0;acc=0});$$('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true};b.onpointerup=b.onpointercancel=()=>{keys[b.dataset.key]=false}});
$('#restart').onclick=$('#again').onclick=()=>{restart();canvas.focus()};$('#reset').onclick=()=>{settings={...defaults};custom=null;world=makeLevel(0);restart();sync();save();toast('A fresh start. Make it yours.')};$('#sound').onclick=()=>{sound=!sound;$('#sound').style.color=sound?'#d99551':'';$('#sound').setAttribute('aria-pressed',sound);toast(sound?'Sound on':'Sound off');tone(650)};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('.canvas-wrap').requestFullscreen()}catch{toast('Fullscreen is unavailable in this browser.')}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:2,settings,world},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='jumpcraft-world.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('World exported. Keep creating!')};$('#import').onclick=()=>$('#file').click();
function validWorld(w){const terrain=w?.blocks||w?.platforms;const point=v=>v&&Number.isFinite(v.x)&&Number.isFinite(v.y);return !!(w&&Array.isArray(terrain)&&Array.isArray(w.coins)&&Array.isArray(w.spikes)&&[...terrain,...w.coins,...w.spikes,w.spawn,...(w.goal?[w.goal]:[])].every(point)&&terrain.every(b=>Number.isFinite(b.w)&&Number.isFinite(b.h)&&b.w>0&&b.h>0&&b.w<=1000&&b.h<=1000))}
$('#file').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>20000000)throw Error();const d=JSON.parse(await f.text());if(!validWorld(d.world))throw Error();let s=d.settings||{};for(let k of ['speed','jump','gravity'])if(!Number.isFinite(s[k])||s[k]<({speed:3,jump:8,gravity:.25}[k])||s[k]>({speed:9,jump:17,gravity:.9}[k]))throw Error();if(!/^#[a-f0-9]{6}$/i.test(s.color)||!['rounded','square','circle'].includes(s.shape)||!palettes[s.theme])throw Error();settings={...defaults,...s,colorName:String(s.colorName||'Custom').slice(0,30),level:[0,1,2].includes(s.level)?s.level:0};world=normalizeWorld(d.world);custom=structuredClone(world);restart();sync();save();toast('Your world is ready. Jump in!')}catch{toast('Could not import. Choose a valid Jumpcraft world file.')}e.target.value=''};
$('#menuButton').onclick=openMenu;$('#closeMenu').onclick=closeMenu;$('#gamesMenu').addEventListener('close',()=>{keys={};jumpHeld=false;last=0;acc=0});$('#newGameForm').onsubmit=e=>{e.preventDefault();createGame($('#newGameName').value);$('#newGameName').value=''};$('#renameForm').onsubmit=e=>{e.preventDefault();const name=$('#renameInput').value.trim();if(!name)return;currentGame().name=name.slice(0,60);save();renderLibrary();toast('Game renamed.')};$('#duplicateGame').onclick=()=>createGame(currentGame().name+' (copy)',true);$('#jumpToggle').onclick=()=>{setDoubleJump(!settings.doubleJump);canvas.focus()};
if(!validWorld(world)){
custom=null;world=makeLevel(0)}world=normalizeWorld(world);if(custom)custom=structuredClone(world);sync();restart();save();requestAnimationFrame(frame);
